<script lang="ts">
  import { onDestroy, tick } from 'svelte';
  import { app, actions, isAdmin, isCashier, displayName, shiftLabel, attendancePermission } from '#lib/state/app';
  import type { Shift, AttendanceRecord } from '#lib/types';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import MetricCard from '#lib/components/MetricCard.svelte';
  import StatusPill from '#lib/components/StatusPill.svelte';
  import EmptyState from '#lib/components/EmptyState.svelte';
  import Modal from '#lib/components/Modal.svelte';
  import Feedback from '#lib/components/Feedback.svelte';
  import { dateLabel, timeLabel, durationLabel, todayJakarta } from '#lib/components/format';
  let mode: 'in' | 'out' | null = null, selectedRecord: AttendanceRecord | null = null;
  let outletId = '', shift: Shift = 'morning', saving = false, locating = false, cameraLoading = false;
  let message = '', failed = false, cameraError = '', geoError = '';
  let location: { latitude: number; longitude: number; accuracy: number } | null = null;
  let video: HTMLVideoElement, stream: MediaStream | null = null, selfie: Blob | null = null, preview = '';
  let filterDate = '', outletFilter = '';
  $: admin = isAdmin($app.user ?? undefined);
  $: cashier = isCashier($app.user ?? undefined);
  $: activeSession = $app.attendanceRecords.find((record) => record.employeeId === $app.user?.id && !record.clockOut);
  $: selectedOutlet = $app.outlets.find((outlet) => outlet.id === outletId);
  $: myRecords = $app.attendanceRecords.filter((record) => record.employeeId === $app.user?.id);
  $: rows = (admin ? $app.attendanceRecords : myRecords).filter((record) => (!filterDate || jakartaDate(record.clockIn) === filterDate) && (!outletFilter || record.outletId === outletFilter)).slice().sort((a, b) => b.clockIn.localeCompare(a.clockIn));
  $: distance = location && selectedOutlet && typeof selectedOutlet.latitude === 'number' && typeof selectedOutlet.longitude === 'number' ? meters(location.latitude, location.longitude, selectedOutlet.latitude, selectedOutlet.longitude) : null;
  $: validLocation = distance !== null && Number.isFinite(distance) && !!selectedOutlet && distance <= selectedOutlet.radiusMeters && !!location && Number.isFinite(location.latitude) && Math.abs(location.latitude) <= 90 && Number.isFinite(location.longitude) && Math.abs(location.longitude) <= 180 && Number.isFinite(location.accuracy) && location.accuracy > 0 && location.accuracy <= 100;
  $: todayRecords = myRecords.filter((record) => jakartaDate(record.clockIn) === todayJakarta());
  const outletName = (id: string) => $app.outlets.find((outlet) => outlet.id === id)?.name ?? '—';
  const jakartaDate = (value: string) => new Intl.DateTimeFormat('en-CA', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: 'Asia/Jakarta' }).format(new Date(value));
  function meters(lat1: number, lon1: number, lat2: number, lon2: number) { const rad = Math.PI / 180; const a = Math.sin((lat2 - lat1) * rad / 2) ** 2 + Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin((lon2 - lon1) * rad / 2) ** 2; return 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); }
  function stopCamera() { stream?.getTracks().forEach((track) => track.stop()); stream = null; }
  function resetSelfie() { selfie = null; if (preview) URL.revokeObjectURL(preview); preview = ''; }
  function close() { mode = null; stopCamera(); resetSelfie(); location = null; }
  function begin(value: 'in' | 'out') { mode = value; outletId = value === 'out' ? activeSession?.outletId ?? '' : $app.user?.outletId ?? ''; shift = 'morning'; message = ''; cameraError = ''; geoError = ''; location = null; resetSelfie(); getLocation(); }
  function getLocation() { if (!navigator.geolocation) { geoError = 'Perangkat ini tidak mendukung lokasi.'; return; } locating = true; location = null; geoError = ''; navigator.geolocation.getCurrentPosition((position) => { location = { latitude: position.coords.latitude, longitude: position.coords.longitude, accuracy: position.coords.accuracy }; locating = false; }, (error) => { locating = false; geoError = error.code === 1 ? 'Akses lokasi ditolak. Izinkan lokasi pada pengaturan browser atau perangkat.' : error.code === 3 ? 'Pencarian lokasi terlalu lama. Coba kembali di area terbuka.' : 'Lokasi belum tersedia. Aktifkan GPS lalu coba kembali.'; }, { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }); }
  async function startCamera() { cameraError = ''; cameraLoading = true; resetSelfie(); try { if (!navigator.mediaDevices?.getUserMedia) throw new Error('Kamera memerlukan HTTPS dan browser yang mendukung akses kamera.'); stopCamera(); stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 640 } }, audio: false }); await tick(); if (mode !== 'in') { stopCamera(); return; } if (video) { video.srcObject = stream; await video.play(); } } catch (error) { stopCamera(); cameraError = error instanceof Error && error.name === 'NotAllowedError' ? 'Akses kamera ditolak. Izinkan kamera di pengaturan browser lalu coba lagi.' : error instanceof Error ? error.message : 'Kamera tidak dapat dibuka.'; } finally { cameraLoading = false; } }
  async function capture() { if (!video?.videoWidth) { cameraError = 'Kamera belum siap. Tunggu sebentar lalu coba kembali.'; return; } const canvas = document.createElement('canvas'); const scale = Math.min(1, 800 / video.videoWidth); canvas.width = Math.round(video.videoWidth * scale); canvas.height = Math.round(video.videoHeight * scale); const context = canvas.getContext('2d'); if (!context) return; context.drawImage(video, 0, 0, canvas.width, canvas.height); const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.8)); if (!blob) { cameraError = 'Selfie belum berhasil diambil. Silakan coba kembali.'; return; } selfie = blob; preview = URL.createObjectURL(blob); stopCamera(); }
  async function submit() { if (!location || !validLocation) { failed = true; message = 'Lokasi harus berada dalam radius outlet dengan akurasi GPS yang memadai.'; return; } if (mode === 'in' && !selfie) { failed = true; message = 'Ambil selfie langsung dari kamera terlebih dahulu.'; return; } saving = true; message = ''; try { if (mode === 'in') await actions.clockIn({ outletId, shift, ...location, selfie: selfie! }); else await actions.clockOut(location); const text = mode === 'in' ? 'Clock in berhasil dicatat. Selamat bekerja!' : 'Clock out berhasil dicatat. Terima kasih untuk hari ini.'; close(); failed = false; message = text; } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Absensi belum berhasil dicatat. Coba kembali.'; } finally { saving = false; } }
  onDestroy(() => { stopCamera(); resetSelfie(); });
</script>

<PageHeading eyebrow="KEHADIRAN KASIR" title="Masuk & pulang" description="Catat kehadiran dengan lokasi outlet dan selfie. Delapan jam, termasuk istirahat."/>
<Feedback {message} error={failed}/>
{#if cashier}<section class="clock-card"><div class="clock-copy"><span class="clock-date">{dateLabel(todayJakarta(), true)} · WIB</span><h2>{activeSession ? 'Semangat untuk hari ini.' : 'Siap memulai hari?'}</h2><p>{activeSession ? `Anda masuk pukul ${timeLabel(activeSession.clockIn)} · ${shiftLabel(activeSession.shift)} di ${outletName(activeSession.outletId)}.` : 'Pilih shift, pastikan lokasi sesuai, lalu ambil selfie untuk mencatat masuk.'}</p><div class="clock-tags"><span><Icon name="pin" size={14}/>Lokasi tervalidasi</span><span><Icon name="camera" size={14}/>Selfie saat masuk</span></div></div><div class="clock-action"><span class="clock-circle"><Icon name={activeSession ? 'logout' : 'clock'} size={36} stroke={1.4}/></span><button class="btn" on:click={() => begin(activeSession ? 'out' : 'in')}><Icon name={activeSession ? 'logout' : 'plus'} size={18}/>{activeSession ? 'Clock out · Pulang' : 'Clock in · Masuk'}</button><small>{activeSession ? 'Lokasi diperiksa kembali saat pulang' : 'Catatan tersimpan setelah berhasil'}</small></div></section>{/if}
<div class="metrics"><MetricCard label={admin ? 'Sedang bekerja' : 'Clock in hari ini'} value={admin ? $app.attendanceRecords.filter((r) => !r.clockOut).length : todayRecords.length ? timeLabel(todayRecords[0].clockIn) : '—'} detail={admin ? 'Catatan yang belum clock out' : activeSession ? shiftLabel(activeSession.shift) : 'Waktu masuk aktual'} icon="clock"/><MetricCard label={admin ? 'Catatan terlambat' : 'Durasi hari ini'} value={admin ? $app.attendanceRecords.filter((r) => r.lateMinutes > 0).length : todayRecords[0]?.durationMinutes != null ? durationLabel(todayRecords[0].durationMinutes) : activeSession ? 'Berjalan' : '—'} detail={admin ? 'Shift pagi dan sore' : 'Target 8 jam termasuk istirahat'} icon="calendar"/><MetricCard label="Target kerja" value="8 jam" detail="Shift Middle mengikuti waktu masuk" icon="sun" accent/></div>
<section class="panel history-panel"><div class="history-heading"><h2>{admin ? 'Catatan kehadiran tim' : 'Riwayat kehadiran Anda'}</h2><div class="filters"><input class="input" type="date" aria-label="Filter tanggal kehadiran" bind:value={filterDate}/>{#if admin}<select class="select" aria-label="Filter outlet kehadiran" bind:value={outletFilter}><option value="">Semua outlet</option>{#each $app.outlets as outlet}<option value={outlet.id}>{outlet.name}</option>{/each}</select>{/if}{#if filterDate || outletFilter}<button class="btn btn-secondary" on:click={() => { filterDate = ''; outletFilter = ''; }}>Reset</button>{/if}</div></div>
  {#if rows.length}<div class="table-wrap"><table><thead><tr>{#if admin}<th>Karyawan</th>{/if}<th>Tanggal & shift</th><th>Masuk</th><th>Pulang</th><th>Durasi</th><th>Status</th><th></th></tr></thead><tbody>{#each rows as record}<tr>{#if admin}<td><strong>{displayName(record.employeeId)}</strong><small>{outletName(record.outletId)}</small></td>{/if}<td>{dateLabel(record.clockIn)}<small>{shiftLabel(record.shift)}</small></td><td>{timeLabel(record.clockIn)}</td><td>{timeLabel(record.clockOut)}</td><td>{durationLabel(record.durationMinutes)}</td><td><StatusPill label={record.lateMinutes ? `Terlambat ${record.lateMinutes} mnt` : !record.clockOut ? 'Berjalan' : record.shift === 'middle' ? 'Middle' : 'Tepat waktu'} tone={record.lateMinutes ? 'amber' : !record.clockOut ? 'blue' : 'green'}/>{#if !record.clockOut && record.lateMinutes > 0}<small>Masih bekerja</small>{/if}{#if attendancePermission(record)}<small>{attendancePermission(record)}</small>{/if}{#if record.source === 'manual'}<small class="corrected">Dicatat manual HR · tanpa validasi GPS/selfie</small>{:else if record.corrected}<small class="corrected">Dikoreksi HR</small>{/if}</td><td><button class="detail-btn" aria-label={`Lihat catatan ${displayName(record.employeeId)} ${dateLabel(record.clockIn)}`} on:click={() => selectedRecord = record}><Icon name="chevron" size={16}/></button></td></tr>{/each}</tbody></table></div>{:else}<EmptyState icon="clock" title="Belum ada catatan kehadiran" description={cashier ? 'Catatan Anda akan muncul setelah clock in berhasil.' : 'Kehadiran kasir akan muncul di sini setelah mereka clock in.'}/>{/if}
</section><p class="footnote"><Icon name="info" size={15}/>Selisih durasi merupakan informasi untuk ditinjau SPV. Tidak otomatis menjadi lembur atau potongan.</p>

<Modal open={mode !== null} title={mode === 'in' ? 'Catat masuk kerja' : 'Catat pulang kerja'} description={mode === 'in' ? 'Lokasi dan selfie wajib agar SPV dapat melakukan pengecekan.' : 'Pastikan Anda masih berada di lokasi outlet.'} onclose={close}>
  {#if mode}<form on:submit|preventDefault={submit}>{#if mode === 'in'}<label class="field">Outlet<select class="select" bind:value={outletId} required><option value="">Pilih outlet</option>{#each $app.outlets.filter((outlet) => outlet.active && outlet.id === $app.user?.outletId) as outlet}<option value={outlet.id}>{outlet.name}</option>{/each}</select></label><fieldset class="shift-choice"><legend>Shift hari ini</legend>{#each (['morning', 'afternoon', ...($app.user?.canMiddleShift ? ['middle'] : [])] as Shift[]) as value}<label class:selected={shift === value}><input type="radio" name="shift" bind:group={shift} value={value}/><Icon name={value === 'morning' ? 'sun' : value === 'afternoon' ? 'moon' : 'clock'} size={21}/><strong>{shiftLabel(value)}</strong><small>{value === 'morning' ? selectedOutlet?.morningStart || '07:00' : value === 'afternoon' ? selectedOutlet?.afternoonStart || '15:00' : 'Fleksibel'} · 8 jam</small></label>{/each}</fieldset>{:else}<div class="outlet-summary"><Icon name="building" size={19}/>{selectedOutlet?.name} · {activeSession ? shiftLabel(activeSession.shift) : ''}</div>{/if}
    <div class="geo-card"><div class="geo-top"><span class="geo-icon"><Icon name="pin" size={21}/></span><div><strong>{locating ? 'Memeriksa lokasi Anda…' : validLocation ? 'Lokasi sesuai' : location ? 'Lokasi belum memenuhi syarat' : 'Lokasi belum tersedia'}</strong><p>{location && distance !== null ? `${Math.round(distance)} m dari outlet · Radius ${selectedOutlet?.radiusMeters} m · Akurasi ±${Math.round(location.accuracy)} m` : 'Aktifkan GPS dan izinkan akses lokasi perangkat.'}</p></div></div>{#if geoError}<p class="geo-error">{geoError}</p>{/if}{#if location && location.accuracy > 100}<p class="geo-error">GPS belum cukup akurat. Coba di area terbuka dan periksa kembali.</p>{/if}{#if selectedOutlet && (selectedOutlet.latitude === null || selectedOutlet.longitude === null)}<p class="geo-error">Lokasi outlet belum diatur. Hubungi Admin HR.</p>{/if}<button class="btn btn-secondary" type="button" on:click={getLocation} disabled={locating}><Icon name="refresh" size={14}/>{locating ? 'Mencari…' : 'Periksa ulang lokasi'}</button></div>
    {#if mode === 'in'}<div class="camera-section"><div class="camera-heading"><h3>Selfie saat masuk</h3><span>Wajib</span></div><div class="camera-preview">{#if preview}<img src={preview} alt="Selfie yang akan dikirim"/>{:else}<video bind:this={video} autoplay muted playsinline aria-label="Pratinjau kamera selfie"></video>{#if !stream}<div class="camera-placeholder"><Icon name="camera" size={34} stroke={1.4}/><p>Ambil foto langsung dari kamera</p><small>Pastikan wajah terlihat dengan jelas</small></div>{/if}{/if}</div><div class="camera-actions">{#if selfie}<button class="btn btn-secondary" type="button" on:click={startCamera}>Ambil ulang</button><span><Icon name="check" size={15}/>Selfie siap</span>{:else if stream}<button class="btn btn-primary" type="button" on:click={capture}><Icon name="camera" size={17}/>Ambil selfie</button>{:else}<button class="btn btn-secondary" type="button" on:click={startCamera} disabled={cameraLoading}><Icon name="camera" size={17}/>{cameraLoading ? 'Membuka kamera…' : 'Buka kamera'}</button>{/if}</div>{#if cameraError}<Feedback message={cameraError} error/>{/if}</div>{/if}
    <Feedback {message} error={failed}/><div class="form-actions"><button class="btn btn-secondary" type="button" on:click={close}>Batal</button><button class="btn btn-primary" type="submit" disabled={saving || locating || !validLocation || (mode === 'in' && !selfie)}>{saving ? 'Mencatat…' : mode === 'in' ? 'Konfirmasi clock in' : 'Konfirmasi clock out'}</button></div>
  </form>{/if}
</Modal>

<Modal open={selectedRecord !== null} title="Detail kehadiran" description={selectedRecord ? `${displayName(selectedRecord.employeeId)} · ${dateLabel(selectedRecord.clockIn)}` : ''} onclose={() => selectedRecord = null}>
  {#if selectedRecord}<div class="attendance-detail"><div class="selfie-view">{#if selectedRecord.selfieUrl}<img src={selectedRecord.selfieUrl} alt={`Selfie masuk ${displayName(selectedRecord.employeeId)}`}/>{:else}<Icon name="camera" size={30}/><p>{selectedRecord.selfiePath ? 'Selfie tersimpan privat. Pratinjau belum tersedia.' : 'Tidak ada selfie pada catatan ini.'}</p>{/if}</div><dl><div><dt>Outlet & shift</dt><dd>{outletName(selectedRecord.outletId)} · {shiftLabel(selectedRecord.shift)}</dd></div><div><dt>Masuk / pulang</dt><dd>{timeLabel(selectedRecord.clockIn)} / {timeLabel(selectedRecord.clockOut)} WIB</dd></div><div><dt>Durasi</dt><dd>{durationLabel(selectedRecord.durationMinutes)}</dd></div><div><dt>Keterlambatan</dt><dd>{selectedRecord.shift === 'middle' ? 'Tidak dihitung untuk Middle' : `${selectedRecord.lateMinutes} menit`}</dd></div>{#if attendancePermission(selectedRecord)}<div><dt>Izin terlambat</dt><dd>{attendancePermission(selectedRecord)}</dd></div>{/if}{#if selectedRecord.source === 'manual'}<div><dt>Sumber pencatatan</dt><dd>Manual oleh HR · GPS dan selfie tidak diverifikasi</dd></div>{/if}<div><dt>Jarak clock in / out</dt><dd>{selectedRecord.inDistance === null ? '—' : `${Math.round(selectedRecord.inDistance)} m`} / {selectedRecord.outDistance == null ? '—' : `${Math.round(selectedRecord.outDistance)} m`}</dd></div><div><dt>Akurasi GPS masuk / pulang</dt><dd>{selectedRecord.inAccuracy == null ? '—' : `±${Math.round(selectedRecord.inAccuracy)} m`} / {selectedRecord.outAccuracy == null ? '—' : `±${Math.round(selectedRecord.outAccuracy)} m`}</dd></div>{#if selectedRecord.corrected}<div><dt>Koreksi HR</dt><dd>{selectedRecord.correctionReason}</dd></div>{/if}</dl></div>{#if admin}<a class="btn btn-secondary" href="/reports"><Icon name="edit" size={16}/>Koreksi melalui rekap HR</a>{/if}{/if}
</Modal>

<style>
.clock-card{display:flex;align-items:center;justify-content:space-between;gap:2rem;background:#f2ecd7;border:1px solid var(--border);border-radius:22px;padding:2.1rem 2.4rem;margin-bottom:1.5rem}.clock-date{font-size:.66rem;letter-spacing:.06em;color:var(--muted)}.clock-copy h2{font-size:1.6rem;letter-spacing:-.05em;color:var(--muted);font-weight:600;margin:.8rem 0}.clock-copy p{font-size:.84rem;line-height:1.8;color:var(--muted);max-width:430px;margin:0}.clock-tags{display:flex;gap:1rem;margin-top:1.1rem;flex-wrap:wrap}.clock-tags>span{display:flex;align-items:center;gap:.4rem;font-size:.66rem;color:var(--muted)}.clock-action{display:flex;flex-direction:column;align-items:center;gap:.85rem;flex-shrink:0}.clock-circle{display:grid;place-items:center;width:76px;height:76px;background:#ebe2c4;border:1px solid var(--border);color:var(--muted);border-radius:50%}.clock-action .btn{background:#70633a;border:1px solid var(--border);color:var(--muted);padding:.8rem 1.35rem}.clock-action small{font-size:.61rem;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin-bottom:1.5rem}.history-panel{padding:0;overflow:hidden}.history-heading{padding:1.3rem;display:flex;justify-content:space-between;gap:1rem;align-items:center;border-bottom:1px solid var(--border)}.history-heading h2{font-size:.94rem;font-weight:600;margin:0;color:var(--muted)}.filters{display:flex;align-items:center;gap:.5rem}.filters input,.filters select{font-size:.73rem;padding:.55rem .65rem;max-width:175px}.filters .btn{padding:.55rem;font-size:.65rem}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left;white-space:nowrap}th{font-size:.64rem;text-transform:uppercase;letter-spacing:.055em;color:var(--muted);font-weight:600;padding:1rem;background:#fcfbf7}td{font-size:.77rem;color:var(--muted);padding:1rem;border-bottom:1px solid var(--border)}td strong{font-weight:600;font-size:.79rem}td small{display:block;color:var(--muted);font-size:.64rem;margin-top:.4rem}.detail-btn{border:0;padding:.5rem;background:transparent;color:var(--muted);cursor:pointer}.footnote{display:flex;gap:.55rem;align-items:flex-start;font-size:.71rem;line-height:1.7;color:var(--muted);margin:1.2rem .2rem}.footnote :global(svg){flex-shrink:0;margin-top:.1rem}.shift-choice{display:flex;gap:.6rem;border:0;margin:1.2rem 0;padding:0}.shift-choice legend{font-size:.75rem;font-weight:600;padding:0 0 .75rem;color:var(--muted)}.shift-choice label{flex:1;display:flex;flex-direction:column;align-items:center;gap:.55rem;border:1px solid var(--border);border-radius:11px;padding:1rem .5rem;background:#fcfaf5;color:var(--muted);cursor:pointer;position:relative}.shift-choice label.selected{background:#f4efde;border-color:var(--border);color:var(--muted)}.shift-choice input{position:absolute;opacity:0;width:1px;height:1px}.shift-choice label:has(input:focus-visible){outline:2px solid #8b7c49;outline-offset:2px}.shift-choice strong{font-size:.76rem;font-weight:600}.shift-choice small{font-size:.62rem}.geo-card{padding:1rem;border:1px solid var(--border);background:#faf8f0;border-radius:12px}.geo-top{display:flex;gap:.75rem;align-items:center}.geo-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:11px;background:#f3eddb;color:var(--muted);flex-shrink:0}.geo-top strong{font-size:.81rem;color:var(--muted)}.geo-top p{font-size:.66rem;line-height:1.7;color:var(--muted);margin:.4rem 0}.geo-card .btn{margin-top:.75rem;font-size:.67rem;padding:.5rem .75rem}.geo-error{font-size:.71rem;color:var(--muted);line-height:1.7;margin:.75rem 0}.camera-section{margin-top:1.5rem}.camera-heading{display:flex;justify-content:space-between;align-items:center}.camera-heading h3{font-size:.82rem;font-weight:600;color:var(--muted);margin:0 0 .9rem}.camera-heading span{font-size:.6rem;color:var(--muted);margin-bottom:.9rem}.camera-preview{height:270px;position:relative;border-radius:14px;overflow:hidden;background:#f6f2e4;border:1px solid var(--border)}.camera-preview video,.camera-preview img{height:100%;width:100%;object-fit:cover}.camera-preview video{transform:scaleX(-1)}.camera-placeholder{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;color:var(--muted)}.camera-placeholder p{font-size:.79rem;margin:.85rem 0 .4rem}.camera-placeholder small{font-size:.65rem;color:var(--muted)}.camera-actions{display:flex;justify-content:center;align-items:center;gap:1rem;margin:1rem 0}.camera-actions span{display:flex;align-items:center;gap:.4rem;font-size:.71rem;color:var(--muted)}.form-actions{display:flex;justify-content:flex-end;gap:.6rem;border-top:1px solid var(--border);margin-top:1.3rem;padding-top:1.2rem}.outlet-summary{display:flex;align-items:center;gap:.6rem;padding:1rem 0;font-size:.85rem;color:var(--muted)}.attendance-detail{display:grid;grid-template-columns:170px 1fr;gap:1.3rem;margin-bottom:1.5rem}.selfie-view{background:#f8f5ea;border:1px solid var(--border);border-radius:12px;min-height:190px;display:flex;align-items:center;justify-content:center;flex-direction:column;color:var(--muted);text-align:center;overflow:hidden}.selfie-view img{width:100%;height:100%;object-fit:cover}.selfie-view p{font-size:.67rem;padding:0 1rem;line-height:1.7}.attendance-detail dl{margin:0;display:grid;gap:1rem}.attendance-detail dt{font-size:.64rem;color:var(--muted);margin:0 0 .35rem}.attendance-detail dd{font-size:.77rem;color:var(--muted);margin:0;line-height:1.5}@media(max-width:900px){.history-heading{align-items:flex-start;flex-direction:column}.clock-card{padding:1.6rem;gap:1rem}.clock-copy h2{font-size:1.4rem}.clock-copy p{font-size:.77rem}}@media(max-width:600px){.clock-card{padding:1.4rem;flex-direction:column;align-items:stretch}.clock-action{align-items:stretch;margin-top:.3rem}.clock-circle{display:none}.clock-action small{text-align:center}.clock-copy h2{font-size:1.4rem}.metrics{gap:.5rem}.metrics :global(.metric){padding:1rem .8rem}.metrics :global(.top){font-size:.65rem}.metrics :global(.icon){display:none}.metrics :global(strong){font-size:1.4rem;line-height:1.2}.metrics :global(p){font-size:.6rem}.filters{flex-wrap:wrap;width:100%}.filters input,.filters select{flex:1;max-width:none;min-width:110px}.history-heading{padding:1rem}.attendance-detail{grid-template-columns:1fr}.selfie-view{height:210px;max-width:250px;min-height:unset}.attendance-detail dl{grid-template-columns:1fr 1fr}.camera-preview{height:250px}.footnote{font-size:.65rem}.shift-choice label{padding:.85rem .4rem}.shift-choice small{font-size:.56rem}}
  .clock-card { background: var(--yellow-soft); border-color: var(--control-border); box-shadow: var(--raised); border-radius: 25px; }
